using Microsoft.EntityFrameworkCore;
class AppDbContext : DbContext
{
    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Fixed: DateTime.UtcNow is non-deterministic and triggers
        // "pending model changes" exception in EF Core 9.
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc) });
    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; }  }

// Cosmos DB context for the separate project with existing documents
class CosmosDbContext : DbContext
{
    public DbSet<Session> Sessions => Set<Session>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "MyDatabase");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Session>(b =>
        {
            b.ToContainer("Sessions");

            // Fix 1: EF Core 9 renamed default discriminator from "Discriminator" to "$type".
            // Existing documents use "Discriminator", so we must explicitly preserve the old name.
            b.HasDiscriminator<string>("Discriminator");

            // Fix 2: EF Core 9 changed id format from "EntityType|Key" to just "Key".
            // Existing documents still have the old compound format; preserve it.
            b.HasRootDiscriminatorInJsonId(true);
        });
    }
}
class Session { public string Id { get; set; } = null!; public string Title { get; set; } = ""; }

// Demonstrates the sync I/O fix for Cosmos DB provider
class CosmosQueryService
{
    // Fix 3: Sync I/O (ToList, SaveChanges) now throws on the Cosmos provider.
    // Must use async equivalents (ToListAsync, SaveChangesAsync).
    public async Task<List<Session>> GetSessionsAsync(CosmosDbContext db)
    {
        return await db.Sessions.ToListAsync();
    }

    public async Task SaveAsync(CosmosDbContext db)
    {
        await db.SaveChangesAsync();
    }
}

